const fs = require('fs');
const path = require('path');

const ENDPOINT = 'http://127.0.0.1:65161/status';

async function main() {
  const res = await fetch(ENDPOINT);
  const resultsDir = path.join(__dirname, 'results');
  fs.mkdirSync(resultsDir, { recursive: true });
  fs.writeFileSync(
    path.join(resultsDir, 'status.json'),
    JSON.stringify({ status: res.status }, null, 2)
  );
  console.log(`status=${res.status}`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

